import re

with open('registry.yaml', 'r') as f:
    content = f.read()

# List of all experiments to extract
experiments = {
    'deepseek_exception_only': ['seed42', 'seed123', 'seed456'],
    'codellama13b_exception_only': ['seed42', 'seed123', 'seed456'],
    'codellama13b_no_trace': ['seed42', 'seed123', 'seed456'],
    'qwen15b_vota': ['seed42', 'seed123', 'seed456'],
    'qwen15b_loop_only': ['seed42', 'seed123', 'seed456'],
    'qwen15b_ae_only': ['seed42', 'seed123', 'seed456'],
    'deepseek_ae_only': ['seed42', 'seed123', 'seed456'],
    'deepseek_loop_only': ['seed42', 'seed123', 'seed456'],
    'codellama13b_vota': ['seed42', 'seed123', 'seed456'],
    'qwen7b_vota': ['seed42', 'seed123', 'seed456'],
    'full_trace_label_only': ['seed42'],
    'label_only': ['seed123', 'seed456'],
}

results = {}

for exp_base, seeds in experiments.items():
    results[exp_base] = {}

    for seed_part in seeds:
        if exp_base == 'full_trace_label_only':
            exp_name = f"{exp_base}_{seed_part}"
        elif exp_base == 'label_only':
            exp_name = f"{exp_base}_{seed_part}"
        else:
            exp_name = f"{exp_base}_{seed_part}"

        # Find in file
        pattern = f"  {exp_name}:"
        if pattern in content:
            start = content.find(pattern)
            # Get section until next experiment (pattern: two spaces + word + colon)
            end = content.find("\n  ", start + 1)
            if end == -1:
                end = start + 5000

            section = content[start:end]

            # Extract accuracy
            acc_match = re.search(r'accuracy:\s+([\d.]+)', section)
            if acc_match:
                accuracy = acc_match.group(1)
                results[exp_base][seed_part] = {
                    'accuracy': accuracy,
                    'found': True
                }
            else:
                results[exp_base][seed_part] = {
                    'accuracy': 'NOT FOUND',
                    'found': False
                }
        else:
            results[exp_base][seed_part] = {
                'accuracy': 'DOES NOT EXIST',
                'found': False
            }

# Print formatted results
for exp_base in sorted(results.keys()):
    print(f"\n{exp_base}:")
    for seed in ['seed42', 'seed123', 'seed456']:
        if seed in results[exp_base]:
            data = results[exp_base][seed]
            status = "✓" if data['found'] else "✗"
            print(f"  {seed}: {data['accuracy']} {status}")
        elif exp_base == 'full_trace_label_only' and seed == 'seed42':
            data = results[exp_base].get(seed, {})
            status = "✓" if data.get('found') else "✗"
            print(f"  {seed}: {data.get('accuracy', 'N/A')} {status}")
        elif exp_base == 'label_only' and seed in ['seed123', 'seed456']:
            data = results[exp_base].get(seed, {})
            status = "✓" if data.get('found') else "✗"
            print(f"  {seed}: {data.get('accuracy', 'N/A')} {status}")

